#include <Adafruit_SSD1306.h>
#include <splash.h>

#include <Adafruit_GFX.h>
#include <Adafruit_PCD8544.h>

// Tested and compiled with no errors
// Arduino Stopwatch with OLED display
// with Start, Stop and Reset button
// source - www.circuitschools.com

#include <SPI.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <Fonts/FreeSans9pt7b.h>
#include <Fonts/FreeSans12pt7b.h>

#define SCREEN_WIDTH 128  // OLED display width, in pixels
#define SCREEN_HEIGHT 64  // OLED display height, in pixels

// SCL A5
// SDA A4
#define OLED_RESET 0  // GPIO0
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

void setup() {
  pinMode(6, INPUT_PULLUP);  //Switch
  pinMode(3, INPUT_PULLUP);
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);  // initialize with the I2C addr 0x3C (for the 128x64)
  display.display();
  display.clearDisplay();
  display.setFont(&FreeSans9pt7b);
  display.setTextColor(WHITE);
  display.setCursor(0, 25);
  //display.println("Circuit Schools");
  display.println("  POZNAIKINO");
  display.display();
  delay(2000);
}

int poz = 1;
int broj = 1;
int kretanjeY = 30;

int sec1 = 0;
int min1 = 0;
unsigned long msec = 0;
unsigned long mili = 0;
int pres = 0;
int fase = 0;
int start = 0;
unsigned long tim = 0;

void loop() {
  //display.clearDisplay();
  if (digitalRead(6) == 0) {
    if (pres == 0) {
      fase = fase + 1;
      pres = 1;

      if (fase >= 2)
        fase = 0;
    }
  } else {
    pres = 0;
  }


  //if(fase==0)
  if (digitalRead(6) == HIGH && digitalRead(3) == LOW)
  {
    display.clearDisplay();
    display.setFont(&FreeSans9pt7b);
    display.setFont();
    display.setCursor(33, 15);
    //display.println("STOPWATCH");
    display.println("POZNAIKINO");
    display.setFont(&FreeSans12pt7b);
    display.setFont();
    display.setCursor(30, 35);
    display.print("Press Start");

    sec1 = 0;
    min1 = 0;
    tim = 0;
    mili = 0;
    msec = 0;
    start = 0;
  }


  if (fase == 1) {
    display.clearDisplay();
    display.setFont(&FreeSans12pt7b);
    display.setFont();
    display.setCursor(37, 0);
    display.print("Stopwatch");
    display.setFont(&FreeSans9pt7b);

    if (start == 0) {
      start = 1;
      tim = millis();
    }
    msec = (millis() - tim);

    min1 = msec / 60000;

    if ((msec / 1000) > 59) {
      sec1 = (msec / 1000) - (min1 * 60);
    } else {
      sec1 = msec / 1000;
    }

    mili = (msec % 1000) / 10;

    display.setCursor(42, 30);
    if (min1 <= 9) {
      display.print("0");
      display.print(min1);
    } else {
      display.print(min1);
    }

    display.print(":");

    if (sec1 <= 9) {
      display.print("0");
      display.print(sec1);
    } else {
      display.print(sec1);
    }
    display.setFont(&FreeSans12pt7b);
    display.setCursor(50, 57);

    if (mili <= 9) {
      display.print("0");
      display.print(mili);
    } else {
      display.print(mili);
    }
  }

  if (fase == 2) {
    display.clearDisplay();
    display.setFont(&FreeSans12pt7b);
    display.setFont();
    display.setCursor(52, 0);
    display.print("Time:");
    display.setFont(&FreeSans9pt7b);
    display.setCursor(42, 30);
    if (min1 <= 9) {
      display.print("0");
      display.print(min1);
    } else {
      display.print(min1);
    }

    display.print(":");

    if (sec1 <= 9) {
      display.print("0");
      display.print(sec1);
    } else {
      display.print(sec1);
    }
    display.setFont(&FreeSans12pt7b);
    display.setCursor(50, 57);

    if (mili <= 9) {
      display.print("0");
      display.print(mili);
    } else {
      display.print(mili);
    }
  }
  display.display();
}
